const Auth=function(){const TOKEN_KEY="skiri_owner_token";const OWNER_KEY="skiri_owner_profile";function saveSession(token,owner){localStorage.setItem(TOKEN_KEY,token);localStorage.setItem(OWNER_KEY,JSON.stringify(owner))}function getToken(){return localStorage.getItem(TOKEN_KEY)}function getOwner(){try{return JSON.parse(localStorage.getItem(OWNER_KEY))}catch(err){return null}}function clearSession(){localStorage.removeItem(TOKEN_KEY);localStorage.removeItem(OWNER_KEY)}async function logout(){const token=getToken();clearSession();if(token){try{await Api.post("logoutOwner",{token:token})}catch(err){}}}async function guardOwnerAuth(){const token=getToken();if(!token){window.location.href="login.html?needStore=1";return null}const res=await Api.post("getOwnerProfile",{token:token});if(!res.ok){clearSession();window.location.href="login.html?expired=1";return null}saveSession(token,res.owner);return res.owner}function showWholesalePendingNotice(owner){if(!owner||owner.storeType!=="wholesaler"&&owner.storeType!=="distributor"||owner.wholesaleVerified)return;const host=document.querySelector("main .container");if(!host||host.querySelector(".wholesale-pending-banner"))return;const note=document.createElement("p");note.className="wholesaler-note wholesale-pending-banner";note.setAttribute("role","status");note.textContent=(owner.storeType==="distributor"?"Distributor":"Wholesale")+" verification pending - Mwakete.com will contact you to schedule a verification call.";host.insertBefore(note,host.firstChild)}return{saveSession:saveSession,getToken:getToken,getOwner:getOwner,clearSession:clearSession,logout:logout,guardOwnerAuth:guardOwnerAuth,showWholesalePendingNotice:showWholesalePendingNotice}}();